// Antwort von POST /upload -> ein Item je Dokumentgruppe (pdf/docx gleicher Basisname)
const s = $input.first().json;
if (s.ok !== true) throw new Error('Upload fehlgeschlagen: ' + (s.error?.message || s.error || JSON.stringify(s)));
if (!s.items.length) throw new Error('Keine verwertbaren Dateien (PDF/Word/STF) hochgeladen.');
return s.items.map(d => ({ json: { ...d, hasPdf: !!d.pdf, hasSource: !!(d.pdf || d.docx || d.doc), hasStf: !!d.stf } }));

const cfg = $('Konfiguration').first().json;
const doc = $('Dokument vorhanden?').item.json;
const a = $json;
if (a.ok !== true) return { json: { ...doc, ok: false, error: 'Analyse fehlgeschlagen: ' + (a.error?.message || a.error || JSON.stringify(a)) } };
const catalog = ($('Platzhalter-Katalog').first().json.entries) || [];
const catalogNames = catalog.map(c => c.name);
const inputFields = a.inputFields || [];
const notes = a.notes || { comments: [], highlights: [], printRules: [], commentPlaceholders: {} };
const highlights = (notes.highlights || []).filter(h => h.text && h.text.trim().length > 1);
const hasFields = a.fields.length > 0 || inputFields.length > 0 || highlights.length > 0;
const system = 'Du ordnest Felder eines Kunden-Dokuments den Platzhaltern der Software AENEAS zu. ' +
  'kundenfelder sind Serienbrieffelder aus Word; eingabefelder sind leere Eingabefelder im PDF (key = Beschriftung des Feldes). ' +
  'Antworte ausschließlich mit JSON im Format {"mapping":[{"field":"<Kundenfeld>","placeholder":"<Platzhalter ohne spitze Klammern oder leer>","confidence":0.0-1.0,"typ":"Text|Datum|Betrag|Zahl|Auswahl","reason":"kurz"}],' +
  '"slots":[{"key":"<key des Eingabefeldes>","text":"<Platzhalter in spitzen Klammern, mehrere durch Leerzeichen getrennt>","confidence":0.0-1.0}]}. ' +
  'markierungen sind farbig markierte Textstellen im Word-Dokument (gelb/rot = variable Stelle, z. B. \"Vorname Nachname\", \"PLZ Ort\", ein Datum); kommentare sind Anweisungen der Mitarbeiter und gehen vor. ' +
  'Zu jeder markierten Stelle, die ein veränderlicher Wert ist, gib in \"textMapping\" [{\"text\":\"<markierter Text exakt>\",\"placeholder\":\"<Platzhalter ohne Klammern; mehrere als <A> <B>>\",\"confidence\":0.0-1.0}] an. Feste Texte (z. B. Behördenname, Ortsangaben) NICHT zuordnen. ' +
  'Verwende NUR Platzhalter aus dem Katalog. Ordne nur zu, wenn die Beschriftung eindeutig passt; sonst weglassen oder confidence unter 0.5. Erfinde nichts.';
const user = JSON.stringify({
  kundenfelder: a.fields,
  eingabefelder: inputFields.map(f => ({ key: f.key, beschriftung: f.label, seite: f.page })),
  textKontext: a.promptContext,
  markierungen: highlights.map(h => ({ text: h.text, farbe: h.color, absatz: h.context })),
  kommentare: (notes.comments || []).map(c => ({ markierterText: c.anchor, kommentar: c.text })),
  platzhalterKatalog: catalog.map(c => ({ name: c.name, anzahl: c.count, beispiel: c.example }))
});
return { json: { ...doc, ok: true, irId: a.irId, highlightTexts: highlights.map(h => h.text), docNotes: { comments: notes.comments || [], printRules: notes.printRules || [], kindHint: notes.kindHint || null }, picturesFound: a.picturesFound || 0, pages: a.pages, fields: a.fields, inputFields, hasFields,
  linesTodo: a.linesTodo, imagesTodo: a.imagesTodo, catalogNames,
  ollamaBody: { model: cfg.model, stream: false, format: 'json', options: { temperature: 0, num_ctx: 16384 },
                messages: [{ role: 'system', content: system }, { role: 'user', content: user }] } } };

const cfg = $('Konfiguration').first().json;
const a = $('Auswerten').item.json;
let mapping = [], slotsRaw = [], textRaw = [], llmError = null;
try {
  const c = String($json.message.content).replace(/```json|```/g, '').trim();
  const p = JSON.parse(c); mapping = Array.isArray(p) ? p : (p.mapping || []); slotsRaw = Array.isArray(p) ? [] : (p.slots || []); textRaw = Array.isArray(p) ? [] : (p.textMapping || []);
} catch (e) { llmError = String($json.error?.message || $json.error || e.message); }
const names = new Set(a.catalogNames);
const map = {}, low = [];
for (const m of mapping) {
  if (!m || !m.field || !a.fields.includes(m.field)) continue;
  const ph = String(m.placeholder || '').replace(/[<>]/g, '').split('|')[0].trim();
  const conf = Number(m.confidence ?? 0);
  if (ph && names.has(ph) && conf >= cfg.minConfidence) map[m.field] = ph;
  else low.push({ field: m.field, placeholder: ph || null, confidence: conf, reason: ph && !names.has(ph) ? 'nicht im Katalog' : 'unsicher' });
}
const slots = {}, slotKeys = new Set((a.inputFields || []).map(f => f.key));
for (const sl of slotsRaw) {
  if (!sl || !sl.key || !slotKeys.has(sl.key)) continue;
  const text = String(sl.text || '').trim(), conf = Number(sl.confidence ?? 0);
  const phs = [...text.matchAll(/<([^<>|]+)(?:\|[^<>]*)?>/g)].map(m => m[1].trim());
  if (phs.length && phs.every(x => names.has(x)) && conf >= cfg.minConfidence) slots[sl.key] = { text, size: 10, dx: 0.5, dy: 0, w: 0, h: 0 };
  else low.push({ field: '[Feld] ' + sl.key, placeholder: text || null, confidence: conf, reason: phs.length && !phs.every(x => names.has(x)) ? 'nicht im Katalog' : 'unsicher' });
}
const textMap = {}, hlSet = new Set(a.highlightTexts || []);
for (const tm of textRaw) {
  if (!tm || !tm.text || !hlSet.has(tm.text)) continue;
  const val = String(tm.placeholder || '').trim(), conf = Number(tm.confidence ?? 0);
  const phs = val.includes('<') ? [...val.matchAll(/<([^<>|]+)(?:\|[^<>]*)?>/g)].map(m => m[1].trim()) : [val.split('|')[0].trim()];
  if (val && phs.every(x => names.has(x)) && conf >= cfg.minConfidence) textMap[tm.text] = val;
  else low.push({ field: '[Markierung] ' + tm.text, placeholder: val || null, confidence: conf, reason: val && !phs.every(x => names.has(x)) ? 'nicht im Katalog' : 'unsicher' });
}
for (const f of a.fields) if (!(f in map) && !low.find(l => l.field === f)) low.push({ field: f, placeholder: null, confidence: 0, reason: 'kein Vorschlag' });
const typOf = ph => /DATUM/.test(ph) ? 'Datum' : /BETRAG|EURO/.test(ph) ? 'Betrag' : /JAHR|ANZAHL/.test(ph) ? 'Zahl' : 'Text';
const fieldList = [
  ...mapping.filter(x => x && x.field && map[x.field]).map(x => ({ feldname: x.field, feldtyp: x.typ || typOf(map[x.field]), platzhalter: map[x.field], sicherheit: Number(x.confidence ?? 0) })),
  ...Object.entries(slots).map(([key, v]) => ({ feldname: key, feldtyp: 'Eingabefeld', platzhalter: v.text, sicherheit: null })),
  ...Object.entries(textMap).map(([text, ph]) => ({ feldname: text, feldtyp: typOf(ph), platzhalter: ph, sicherheit: null }))
];
return { json: { baseName: a.baseName, pdf: a.pdf, irId: a.irId, mapped: map, slots, textMap, low, llmError, docNotes: a.docNotes, fieldList } };

const cfg = $('Konfiguration').first().json;
const a = $('Auswerten').item.json;
return { json: { baseName: a.baseName, pdf: a.pdf, irId: a.irId, mapped: {}, slots: {}, textMap: {}, docNotes: a.docNotes, low: [], llmError: null, note: 'Keine Word-Felder gefunden - Platzhalter müssen manuell gesetzt werden' } };

let ctx;
try { ctx = $('Mapping prüfen').item.json; } catch (e) { ctx = $('Ohne Mapping').item.json; }
const g = $json;
if (g.ok !== true) return { json: { kind: 'error', baseName: ctx.baseName, error: 'Erzeugen fehlgeschlagen: ' + (g.error?.message || g.error || JSON.stringify(g)) } };
return { json: { kind: 'ok', baseName: ctx.baseName, stf: g.stf, renamed: g.renamed, pages: g.pages, texts: g.texts,
  placeholders: g.placeholders, unmapped: g.unmappedFields, low: ctx.low, llmError: ctx.llmError, note: ctx.note || null,
  linesTodo: g.linesTodo, imagesTodo: g.imagesTodo, linesMade: g.linesMade, slotsFilled: g.slotsFilled,
  typ: g.kind, typSicherheit: g.kindConfidence, vorlageQuelle: g.templateSource, vorlageOrdner: g.templateFolder, vorlageStand: g.templateModified, pruefen: g.needsReview, pruefGruende: g.reviewReasons || [], fieldList: ctx.fieldList || [], modus: g.mode, textOnly: g.textOnly === true, vorlage: g.template, aehnlichkeit: g.similarity, importModus: g.importMode,
  ersetzeZiel: g.replaceTarget, vorschau: g.previewPdf, manifest: g.manifest, hinweise: g.notes || [], docKommentare: g.docComments || [], druckregeln: g.printRules || [], bilderEingefuegt: g.picturesMade || 0, markierungenErsetzt: g.textMapped || 0 } };

const cfg = $('Konfiguration').first().json;
const items = $input.all().map(i => i.json);
const ok = items.filter(i => i.kind === 'ok'), err = items.filter(i => i.kind === 'error'), stf = items.filter(i => i.kind === 'stf');
const noPdf = $('Dokumente aufteilen').all().map(i => i.json).filter(d => !d.hasSource && !d.hasStf);
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
let h = `<p>Die KI hat die Formulare für <b>${esc(cfg.kunde)}</b> verarbeitet.</p>`;
h += `<p><b>${ok.length}</b> Formular(e) erzeugt, <b>${err.length}</b> Fehler, <b>${noPdf.length}</b> übersprungen, <b>${stf.length}</b> STF-Datei(en) verarbeitet.<br>Ausgabeordner auf dem Server: <code>${esc(cfg.outDir)}</code></p>`;
for (const r of ok) {
  h += `<hr><p><b>${esc(r.stf.split(/[\\\/]/).pop())}</b> – ${r.pages} Seite(n), ${r.texts} Textboxen<br>Platzhalter: ${esc((r.placeholders || []).join(', ')) || '–'}</p>`;
  h += `<p>Typ: <b>${esc(r.typ)}</b> (Sicherheit ${esc(r.typSicherheit)}) · Erzeugung: <b>${r.modus === 'bescheid' ? 'vorhandenen Bescheid bearbeitet' : r.modus === 'inherit' ? 'auf Basis eines ähnlichen Formulars' : 'von Grund auf'}</b>${r.vorlage ? ` (Vorlage: ${esc(r.vorlage)}, Ähnlichkeit ${esc(r.aehnlichkeit)})` : ''}<br>Import in Aeneas: <b>${r.importModus === 'Ersetzen' ? 'ERSETZEN von „' + esc(r.ersetzeZiel) + '“ (Vorlage laden → Ersetzen)' : 'Neu anlegen'}</b>${r.vorschau ? `<br>Vorschau-PDF zur Prüfung: <code>${esc(r.vorschau)}</code> (rot = Original, schwarz/blau = erzeugt; Näherung, nicht der Designer-Ausdruck)` : ''}</p>`;
  if (r.vorlageQuelle === 'qdrant') h += `<p>Vorlage aus der Qdrant-Datenbank: <b>${esc(r.vorlage)}</b> (${esc(r.vorlageOrdner)}, Stand ${esc(String(r.vorlageStand || '').slice(0, 10))})</p>`;
  if (r.textOnly) h += '<p><b>Word ohne PDF (Nur-Text-Modus):</b> übernommen wurde nur der Text; Positionen, Linien und Bilder stammen aus der Vorlage' + (r.vorlage ? ` „${esc(r.vorlage)}“` : '') + ' (bzw. einfacher Fließtext, wenn keine Vorlage gefunden wurde). Bitte das Layout in AENEAS besonders sorgfältig prüfen.</p>';
  if (r.pruefen) h += '<p><b>Bitte besonders prüfen:</b></p><ul>' + (r.pruefGruende || []).map(x => `<li>${esc(x)}</li>`).join('') + '</ul>';
  if (r.fieldList?.length) h += '<p>Felder und Platzhalter (JSON):</p><pre style="font-size:11px">' + esc(JSON.stringify(r.fieldList, null, 1)) + '</pre>';
  const todo = [];
  if (r.bilderEingefuegt) h += `<p>Logos/Wappen automatisch eingefügt: <b>${r.bilderEingefuegt}</b> · markierte Stellen durch Platzhalter ersetzt: <b>${r.markierungenErsetzt}</b></p>`;
  if (r.docKommentare?.length) h += '<p><b>Kommentare aus dem Word-Dokument (bitte beachten):</b></p><ul>' + r.docKommentare.map(k => `<li>${esc(k)}</li>`).join('') + '</ul>';
  if (r.druckregeln?.length) h += '<p><b>Druck-/Anhängeregeln laut Kommentar (in Aeneas einzurichten):</b></p><ul>' + r.druckregeln.map(k => `<li>${esc(k)}</li>`).join('') + '</ul>';
  for (const n of (r.hinweise || []).slice(0, 8)) todo.push(n);
  if (r.unmapped?.length) todo.push('Nicht zugeordnete Felder: ' + r.unmapped.join(', '));
  if (r.low?.length) todo.push('Unsichere Zuordnungen: ' + r.low.map(l => `${l.field}→${l.placeholder || '?'} (${l.reason})`).join('; '));
  if (r.linesTodo) todo.push(`${r.linesTodo} Linien/Rahmen noch von Hand`);
  if (r.imagesTodo) todo.push(`${r.imagesTodo} Bild(er)/Logo konnten nicht automatisch übernommen werden (z. B. JPEG) - bitte von Hand einfügen`);
  if (r.renamed) todo.push('Datei existierte bereits - neue Datei wurde als ' + r.stf.split(/[\\\/]/).pop() + ' gespeichert (nichts überschrieben)');
  if (r.llmError) todo.push('KI-Fehler: ' + r.llmError);
  if (r.note) todo.push(r.note);
  if (todo.length) h += '<ul>' + todo.map(t => `<li>${esc(t)}</li>`).join('') + '</ul>';
}
if (err.length) h += '<hr><p><b>Fehler</b></p><ul>' + err.map(e => `<li>${esc(e.baseName)}: ${esc(e.error)}</li>`).join('') + '</ul>';
if (stf.length) h += '<hr><p><b>Hochgeladene STF-Dateien</b> (nicht neu gebaut: als Vorlage aufgenommen bzw. daraus gelernt):</p><ul>' + stf.map(x => '<li><b>' + esc(x.baseName) + '</b>: ' + (x.ok ? esc((x.actions || []).join(' + ')) + (x.learned ? ` (Textpaare verglichen: ${esc(x.learned.textPairs)})` : '') + (x.generated ? ' – Bezug: ' + esc(String(x.generated).split(/[\\\/]/).pop()) : '') : '<b>FEHLER:</b> ' + esc(x.error)) + ((x.warnings || []).length ? ' – ' + esc(x.warnings.join('; ')) : '') + '</li>').join('') + '</ul>';
if (noPdf.length) h += '<hr><p><b>Übersprungen</b> (weder PDF noch Word zum Nachbauen vorhanden, z. B. reine .stf-Dateien): ' + noPdf.map(d => esc(d.baseName)).join(', ') + '</p>';
h += '<hr><p>Bitte in AENEAS prüfen (ausgefüllter Ausdruck/PDF). Nach der Korrektur in Aeneas die korrigierte Fassung exportieren und über den Workflow „Aeneas-Formulare lernen“ melden, damit die KI daraus lernt. Import der erzeugten Dateien: manifest.csv im Ausgabeordner (FormulareImport).</p>';
return [{ json: { subject: `Aeneas-Formulare: ${cfg.kunde} – ${ok.length} erzeugt, ${err.length} Fehler${stf.length ? ', ' + stf.length + ' STF' : ''}`, html: h, to: cfg.email || cfg.standardEmail || '', from: cfg.mailFrom } }];

const item = $input.first();
const files = [];
for (const key of Object.keys(item.binary || {})) {
  const b = item.binary[key];
  const buf = await this.helpers.getBinaryDataBuffer(0, key);
  files.push({ name: b.fileName || key, base64: buf.toString('base64') });
}
if (!files.length) throw new Error('Bitte mindestens eine Datei hochladen.');
return [{ json: { ...item.json, files } }];

// Antwort von POST /stf/ingest (eine Datei je Aufruf)
const doc = $('STF hochgeladen?').item.json;
const g = $json, r = (g.results || [])[0] || null;
const err = r ? (r.ok === true ? null : (r.error || 'unbekannter Fehler')) : String(g.error?.message || g.error || JSON.stringify(g));
return { json: { kind: 'stf', baseName: doc.baseName, ok: !err, error: err, actions: r?.actions || [], warnings: r?.warnings || [], generated: r?.generated || null,
  learned: r?.learned || null, templatePath: r?.templatePath || null, embedSource: r?.embedSource || null } };
